#pragma once

#include <algorithm>
#include <cstdint>

namespace dxvk {

  inline bool bridgeValidMappedChunkSize(int32_t value) {
    return value == 0 || value == 16 || value == 32 || value == 64;
  }

  inline uint64_t bridgeMappedChunkLimit(uint64_t upstream, int32_t value) {
    if (!value || !bridgeValidMappedChunkSize(value)) {
      return upstream;
    }
    return std::min(upstream, uint64_t(value) << 20u);
  }

  // The allocator mutex protects this list. Nodes retain no extra references.
  template<typename T>
  class BridgeMemoryList {
  public:
    T* head() const { return m_head; }

    void add(T* node) {
      node->m_bridgePrev = nullptr;
      node->m_bridgeNext = m_head;
      if (m_head) {
        m_head->m_bridgePrev = node;
      }
      m_head = node;
    }

    void remove(T* node) {
      if (node->m_bridgePrev) {
        node->m_bridgePrev->m_bridgeNext = node->m_bridgeNext;
      } else {
        m_head = node->m_bridgeNext;
      }
      if (node->m_bridgeNext) {
        node->m_bridgeNext->m_bridgePrev = node->m_bridgePrev;
      }
      node->m_bridgePrev = nullptr;
      node->m_bridgeNext = nullptr;
    }

  private:
    T* m_head = nullptr;
  };

}
